		'/glossary/' => array(
			'intro' => '<p>Clear, one-line-first definitions of the terms that matter in AI and AI search. Written to be genuinely useful to readers — and structured with DefinedTerm schema so AI answer engines can cite them.</p>',
			'def' => '',
			'cards' => array(),
			'steps' => array(),
			'outcomes' => '',
			'who' => '',
			'faqs' => array(),
			'sections' => array(array('h'=>'A–Z of terms','html'=>'<p><code>[Alphabetical list — each links to /glossary/{term}/. Seed terms below; expand over time.]</code></p>
