		'/industries/' => array(
			'intro' => '<p>AI pays off fastest when it\'s applied to the specific workflows of your sector. Alugence builds AI for the way your industry actually works — from underwriting in financial services to predictive maintenance in manufacturing. Choose your sector to see the use cases we deliver.</p>',
			'def' => '',
