			'who' => '',
			'faqs' => array(),
			'sections' => array(array('h'=>'Sectors we work in','html'=>'<ul><li><a href="/industries/financial-services/">AI for Financial Services</a> — underwriting, compliance, onboarding.</li><li><a href="/industries/healthcare-dental/">AI for Healthcare &amp; Dental</a> — patient comms, no-shows, clinical admin.</li><li><a href="/industries/professional-services/">AI for Professional Services</a> — drafting, research, admin.</li><li><a href="/industries/legal/">AI for Legal &amp; Law Firms</a> — contract review, research, drafting.</li><li><a href="/industries/retail-ecommerce/">AI for Retail &amp; E-commerce</a> — personalisation, forecasting, analytics.</li><li><a href="/industries/real-estate/">AI for Real Estate &amp; Property</a> — valuations, listings, lead qualification.</li><li><a href="/industries/logistics-transport/">AI for Logistics &amp; Transport</a> — routing, dispatch, fleet.</li><li><a href="/industries/construction/">AI for Construction &amp; Engineering</a> — estimating, documents, risk.</li><li><a href="/industries/manufacturing/">AI for Manufacturing</a> — predictive maintenance, QA, process.</li><li><a href="/industries/marketing-agencies/">AI for Marketing &amp; Agencies</a> — content, reporting, GEO/AEO.</li></ul>'),array('h'=>'Don\'t see your sector?','html'=>'<p>The principles apply across industries. <a href="/contact/">Book a discovery call →</a> and we\'ll map the highest-value AI use cases for your business.</p>')),
		),
		'/industries/construction/' => array(
			'intro' => '<p>AI in construction and engineering means using artificial intelligence to speed up estimating, process documents and drawings, and analyse project risk. Alugence helps contractors, engineers and construction firms deploy practical AI that cuts admin, improves accuracy, and helps projects stay on time and on budget.</p>',
			'def' => '',
			'cards' => array(array('title'=>'Estimating','body'=>'<p>faster, more consistent take-offs and quotes.</p>'),array('title'=>'Document & drawing processing','body'=>'<p>extracting data from plans and specs.</p>'),array('title'=>'Risk analysis','body'=>'<p>flagging cost and schedule risks early.</p>'),array('title'=>'Health & safety compliance','body'=>'<p>automating checks and records.</p>'),array('title'=>'RFI automation','body'=>'<p>faster handling of requests for information.</p>')),
			'steps' => array(),
			'outcomes' => '<p>Construction is document-heavy and margin-sensitive, and small estimating or admin errors get expensive fast. We deploy AI that reads plans, specs and documents to speed up estimating and reduce mistakes, with a human always checking consequential outputs. The result is more bids out the door and fewer costly surprises.</p>',
			'who' => '<p>Firms often start with <a href="/ai-consultancy/ai-automation/">document automation</a> for estimating and RFIs, then add <a href="/ai-consultancy/predictive-analytics/">predictive analytics</a> for risk.</p>',
			'faqs' => array(array('How can AI help construction and engineering firms?','AI can speed up estimating and take-offs, extract data from drawings and specifications, flag project risks early, automate health-and-safety records, and handle RFIs faster. This reduces admin, improves accuracy, and helps keep projects on time and on budget.'),array('Can AI read construction drawings and documents?','Yes. AI can extract and structure information from plans, specifications and project documents, speeding up estimating and reducing manual data entry. Outputs are checked by your team, so accuracy and accountability are maintained on consequential work.'),array('What\'s a practical first AI project in construction?','Automating document-heavy estimating or RFI handling is a common, practical starting point — it targets a clear bottleneck and delivers visible time savings. We assess your workflows and prioritise the use case with the best return.')),
			'sections' => array(array('h'=>'Where AI adds value in construction','html'=>'<ul><li><strong>Estimating</strong> — faster, more consistent take-offs and quotes.</li><li><strong>Document &amp; drawing processing</strong> — extracting data from plans and specs.</li><li><strong>Risk analysis</strong> — flagging cost and schedule risks early.</li><li><strong>Health &amp; safety compliance</strong> — automating checks and records.</li><li><strong>RFI automation</strong> — faster handling of requests for information.</li></ul>'),array('h'=>'Why Alugence for construction','html'=>'<p>Construction is document-heavy and margin-sensitive, and small estimating or admin errors get expensive fast. We deploy AI that reads plans, specs and documents to speed up estimating and reduce mistakes, with a human always checking consequential outputs. The result is more bids out the door and fewer costly surprises.</p>'),array('h'=>'How we work','html'=>'<p>Firms often start with <a href="/ai-consultancy/ai-automation/">document automation</a> for estimating and RFIs, then add <a href="/ai-consultancy/predictive-analytics/">predictive analytics</a> for risk.</p>')),
		),
		'/industries/financial-services/' => array(
			'intro' => '<p>AI in financial services means using artificial intelligence to automate and improve regulated processes — underwriting, compliance, onboarding, fraud detection and reporting — safely and within the rules. Alugence helps banks, lenders, insurers and finance teams adopt AI where it pays off fastest, with governance and compliance built in from the start.</p>',
			'def' => '',
			'cards' => array(array('title'=>'Underwriting automation','body'=>'<p>faster, more consistent risk assessment.</p>'),array('title'=>'AML & compliance checks','body'=>'<p>automated screening and monitoring.</p>'),array('title'=>'Onboarding & KYC','body'=>'<p>quicker, smoother client onboarding.</p>'),array('title'=>'Fraud detection','body'=>'<p>spotting anomalies in real time.</p>'),array('title'=>'Client reporting','body'=>'<p>automated, accurate reporting and summaries.</p>')),
			'steps' => array(),
			'outcomes' => '<p>Financial services can\'t treat AI as a science experiment — it has to be accurate, explainable and compliant. We pair AI delivery with strong <a href="/ai-consultancy/ai-governance/">governance</a>, mapping your obligations under UK rules, the EU AI Act and GDPR, and designing human oversight into higher-risk decisions. You get value <em>and</em> a deployment that survives audit.</p>',
			'who' => '<p>Most firms start with an <a href="/ai-consultancy/ai-readiness/">AI Readiness Assessment</a>, then a <a href="/ai-consultancy/ai-proof-of-concept/">proof of concept</a> on a single process like onboarding, before scaling into production with the right controls.</p>',
			'faqs' => array(array('How is AI used in financial services?','AI in financial services automates and augments processes such as underwriting, anti-money-laundering and compliance checks, client onboarding and KYC, fraud detection, and reporting. It speeds up regulated work and improves consistency, provided it\'s deployed with appropriate governance and human oversight.'),array('Is AI safe to use in a regulated finance environment?','Yes, when deployed responsibly. That means classifying use cases by risk, keeping humans in the loop for consequential decisions, ensuring explainability, and aligning with UK regulation, the EU AI Act and GDPR. Alugence designs these controls in from the start — see AI governance.'),array('What\'s the fastest AI win for a finance business?','Often onboarding and document-heavy compliance work, where AI can extract, check and summarise information that staff currently handle manually. We assess your processes and prioritise the use case with the best balance of value, effort and risk.')),
			'sections' => array(array('h'=>'Where AI adds value in financial services','html'=>'<ul><li><strong>Underwriting automation</strong> — faster, more consistent risk assessment.</li><li><strong>AML &amp; compliance checks</strong> — automated screening and monitoring.</li><li><strong>Onboarding &amp; KYC</strong> — quicker, smoother client onboarding.</li><li><strong>Fraud detection</strong> — spotting anomalies in real time.</li><li><strong>Client reporting</strong> — automated, accurate reporting and summaries.</li></ul>'),array('h'=>'Why Alugence for financial services','html'=>'<p>Financial services can\'t treat AI as a science experiment — it has to be accurate, explainable and compliant. We pair AI delivery with strong <a href="/ai-consultancy/ai-governance/">governance</a>, mapping your obligations under UK rules, the EU AI Act and GDPR, and designing human oversight into higher-risk decisions. You get value <em>and</em> a deployment that survives audit.</p>'),array('h'=>'How we work','html'=>'<p>Most firms start with an <a href="/ai-consultancy/ai-readiness/">AI Readiness Assessment</a>, then a <a href="/ai-consultancy/ai-proof-of-concept/">proof of concept</a> on a single process like onboarding, before scaling into production with the right controls.</p>')),
		),
		'/industries/healthcare-dental/' => array(
			'intro' => '<p>AI in healthcare and dental practices means using artificial intelligence to reduce no-shows, automate patient communications, and streamline clinical admin — freeing clinicians and staff to focus on care. Alugence helps practices and providers adopt practical, compliant AI that improves both efficiency and patient experience.</p>',
			'def' => '',
			'cards' => array(array('title'=>'No-show reduction','body'=>'<p>smart reminders and easy rescheduling.</p>'),array('title'=>'Patient comms','body'=>'<p>automated, on-brand replies to common enquiries.</p>'),array('title'=>'Clinical admin','body'=>'<p>summarising records and automating paperwork.</p>'),array('title'=>'Triage assistants','body'=>'<p>guiding patients to the right care.</p>'),array('title'=>'Records summarisation','body'=>'<p>faster access to relevant history.</p>')),
			'steps' => array(),
			'outcomes' => '<p>Patient data is sensitive and heavily regulated, so AI here must be private, accurate and compliant. We build with data protection and clinical safety front of mind, aligning to GDPR and sector requirements, and keeping clinicians in control of clinical decisions. The result is AI that saves time without adding risk.</p>',
			'who' => '<p>Practices often start with a <a href="/ai-consultancy/ai-chatbots/">chatbot</a> or <a href="/ai-consultancy/voice-ai/">voice AI</a> agent for reminders and enquiries — a quick, visible win — then extend into clinical admin with the right <a href="/ai-consultancy/ai-governance/">governance</a>.</p>',
			'faqs' => array(array('How can AI help a dental or healthcare practice?','AI can cut no-shows with smart reminders, answer patient enquiries and handle bookings 24/7, automate clinical and administrative paperwork, and summarise records so clinicians spend less time on admin. These improve efficiency and patient experience while keeping clinical decisions with clinicians.'),array('Is patient data safe with AI?','It can be, with the right controls. That means using appropriate, compliant tools, restricting what data is processed and where, aligning with GDPR and sector rules, and keeping humans in control of clinical decisions. We design these safeguards into every healthcare deployment.'),array('What\'s a good first AI project for a practice?','Reducing no-shows and automating patient communications is a common, high-value starting point — an AI assistant that handles reminders, rescheduling and routine enquiries. It\'s visible, quick to deliver, and frees front-desk staff immediately.')),
			'sections' => array(array('h'=>'Where AI adds value in healthcare and dental','html'=>'<ul><li><strong>No-show reduction</strong> — smart reminders and easy rescheduling.</li><li><strong>Patient comms</strong> — automated, on-brand replies to common enquiries.</li><li><strong>Clinical admin</strong> — summarising records and automating paperwork.</li><li><strong>Triage assistants</strong> — guiding patients to the right care.</li><li><strong>Records summarisation</strong> — faster access to relevant history.</li></ul>'),array('h'=>'Why Alugence for healthcare and dental','html'=>'<p>Patient data is sensitive and heavily regulated, so AI here must be private, accurate and compliant. We build with data protection and clinical safety front of mind, aligning to GDPR and sector requirements, and keeping clinicians in control of clinical decisions. The result is AI that saves time without adding risk.</p>'),array('h'=>'How we work','html'=>'<p>Practices often start with a <a href="/ai-consultancy/ai-chatbots/">chatbot</a> or <a href="/ai-consultancy/voice-ai/">voice AI</a> agent for reminders and enquiries — a quick, visible win — then extend into clinical admin with the right <a href="/ai-consultancy/ai-governance/">governance</a>.</p>')),
		),
		'/industries/legal/' => array(
			'intro' => '<p>AI for law firms means using artificial intelligence to speed up contract review, legal research, drafting and due diligence — securely and with appropriate oversight. Alugence helps legal teams deploy AI built for their workflows and confidentiality requirements, so lawyers spend less time on routine review and more on judgement and client work.</p>',
			'def' => '',
			'cards' => array(array('title'=>'Contract review','body'=>'<p>faster first-pass review and issue spotting.</p>'),array('title'=>'Legal research','body'=>'<p>quicker retrieval and summarising of relevant material.</p>'),array('title'=>'Drafting','body'=>'<p>first drafts of standard documents and clauses.</p>'),array('title'=>'Due diligence','body'=>'<p>accelerated document review at scale.</p>'),array('title'=>'Matter summarisation','body'=>'<p>concise summaries of long files.</p>')),
			'steps' => array(),
			'outcomes' => '<p>Accuracy, confidentiality and professional duty are non-negotiable in law. We deploy AI as an assistant under lawyer supervision — never as a replacement for legal judgement — with secure tooling, controlled data handling and clear human review. That gives firms speed without compromising their obligations.</p>',
			'who' => '<p>Firms often start with a secure <a href="/ai-consultancy/llm-deployment/">LLM deployment</a> and <a href="/ai-consultancy/ai-training/">training</a>, then add contract-review or research assistants grounded in their own precedents, with <a href="/ai-consultancy/ai-governance/">governance</a> throughout.</p>',
			'faqs' => array(array('How is AI used in law firms?','AI helps law firms with contract review and issue spotting, legal research and summarisation, drafting standard documents, and accelerating due diligence. Used as a supervised assistant, it speeds up routine, document-heavy work while lawyers retain responsibility for legal judgement and final output.'),array('Is AI accurate enough for legal work?','AI is a powerful assistant but not a substitute for legal expertise. It can surface, summarise and draft quickly, but outputs must be checked by a qualified lawyer. We design workflows with mandatory human review and grounding in your own reliable sources to manage accuracy and risk.'),array('How do you protect client confidentiality and privilege?','We use secure, appropriately licensed tools, tightly control what data is processed and where, and align deployments with your confidentiality, privilege and GDPR obligations. Sensitive matters stay within controlled environments, with human oversight at every step.')),
			'sections' => array(array('h'=>'Where AI adds value in legal','html'=>'<ul><li><strong>Contract review</strong> — faster first-pass review and issue spotting.</li><li><strong>Legal research</strong> — quicker retrieval and summarising of relevant material.</li><li><strong>Drafting</strong> — first drafts of standard documents and clauses.</li><li><strong>Due diligence</strong> — accelerated document review at scale.</li><li><strong>Matter summarisation</strong> — concise summaries of long files.</li></ul>'),array('h'=>'Why Alugence for legal','html'=>'<p>Accuracy, confidentiality and professional duty are non-negotiable in law. We deploy AI as an assistant under lawyer supervision — never as a replacement for legal judgement — with secure tooling, controlled data handling and clear human review. That gives firms speed without compromising their obligations.</p>'),array('h'=>'How we work','html'=>'<p>Firms often start with a secure <a href="/ai-consultancy/llm-deployment/">LLM deployment</a> and <a href="/ai-consultancy/ai-training/">training</a>, then add contract-review or research assistants grounded in their own precedents, with <a href="/ai-consultancy/ai-governance/">governance</a> throughout.</p>')),
		),
		'/industries/logistics-transport/' => array(
			'intro' => '<p>AI in logistics and transport means using artificial intelligence to optimise routes, automate dispatch, and improve fleet utilisation — cutting fuel, time and cost. Alugence helps logistics operators, hauliers and transport firms deploy practical AI that makes operations more efficient and more predictable.</p>',
			'def' => '',
			'cards' => array(array('title'=>'Route optimisation','body'=>'<p>smarter, cheaper, faster routing.</p>'),array('title'=>'Dispatch automation','body'=>'<p>allocating jobs efficiently.</p>'),array('title'=>'Fleet utilisation','body'=>'<p>getting more from every vehicle.</p>'),array('title'=>'Demand forecasting','body'=>'<p>planning capacity ahead of need.</p>'),array('title'=>'ETA prediction','body'=>'<p>accurate arrival times for customers.</p>')),
			'steps' => array(),
			'outcomes' => '<p>Logistics runs on thin margins and tight schedules, so AI has to deliver measurable efficiency — less empty running, fewer missed slots, lower fuel. We prioritise the use cases with the clearest cost impact, integrate with your systems, and quantify the saving.</p>',
			'who' => '<p>Operators often begin with <a href="/ai-consultancy/predictive-analytics/">predictive analytics</a> for forecasting and routing, plus <a href="/ai-consultancy/ai-automation/">automation</a> of dispatch and admin.</p>',
			'faqs' => array(array('How is AI used in logistics and transport?','AI optimises route planning, automates dispatch and job allocation, improves fleet utilisation, forecasts demand, and predicts accurate ETAs. Together these cut fuel and time costs, reduce empty running, and improve on-time performance and customer communication.'),array('What\'s the biggest cost saving AI can deliver in transport?','Route and fleet optimisation usually offer the largest, most direct savings — reducing miles, fuel and idle capacity. Dispatch automation and better forecasting add further efficiency. We assess your operation and target the highest-impact use case first.'),array('Can AI integrate with our existing fleet or TMS systems?','Yes. We integrate AI with your transport management, telematics and scheduling systems so it acts on live data rather than sitting in a silo. Integration is core to getting real operational value.')),
			'sections' => array(array('h'=>'Where AI adds value in logistics','html'=>'<ul><li><strong>Route optimisation</strong> — smarter, cheaper, faster routing.</li><li><strong>Dispatch automation</strong> — allocating jobs efficiently.</li><li><strong>Fleet utilisation</strong> — getting more from every vehicle.</li><li><strong>Demand forecasting</strong> — planning capacity ahead of need.</li><li><strong>ETA prediction</strong> — accurate arrival times for customers.</li></ul>'),array('h'=>'Why Alugence for logistics','html'=>'<p>Logistics runs on thin margins and tight schedules, so AI has to deliver measurable efficiency — less empty running, fewer missed slots, lower fuel. We prioritise the use cases with the clearest cost impact, integrate with your systems, and quantify the saving.</p>'),array('h'=>'How we work','html'=>'<p>Operators often begin with <a href="/ai-consultancy/predictive-analytics/">predictive analytics</a> for forecasting and routing, plus <a href="/ai-consultancy/ai-automation/">automation</a> of dispatch and admin.</p>')),
		),
		'/industries/manufacturing/' => array(
			'intro' => '<p>AI in manufacturing means using artificial intelligence to predict maintenance, automate quality assurance, and optimise processes — cutting downtime, waste and cost. Alugence helps manufacturers deploy practical AI on the factory floor and across the supply chain, turning production and sensor data into fewer breakdowns and better yield.</p>',
			'def' => '',
			'cards' => array(array('title'=>'Predictive maintenance','body'=>'<p>fix machines before they fail.</p>'),array('title'=>'Quality assurance & vision','body'=>'<p>automated defect detection.</p>'),array('title'=>'Process optimisation','body'=>'<p>tuning production for yield and efficiency.</p>'),array('title'=>'Demand planning','body'=>'<p>matching output to real demand.</p>'),array('title'=>'Supply chain','body'=>'<p>smarter forecasting and inventory.</p>')),
			'steps' => array(),
			'outcomes' => '<p>Downtime and defects are the two biggest destroyers of manufacturing margin, and both are highly predictable with the right data. We deploy AI that turns your machine and production data into early warnings and quality checks, integrated with your systems and measured against real output.</p>',
			'who' => '<p>Manufacturers often start with a <a href="/ai-consultancy/predictive-analytics/">predictive analytics</a> pilot for maintenance or quality, then scale into production with <a href="/ai-consultancy/mlops/">MLOps</a> for reliability.</p>',
			'faqs' => array(array('How is AI used in manufacturing?','AI in manufacturing enables predictive maintenance (fixing equipment before it fails), automated quality assurance using computer vision, process optimisation for yield and efficiency, demand planning, and smarter supply-chain forecasting. These reduce downtime, waste and cost while improving quality.'),array('What is predictive maintenance?','Predictive maintenance uses AI to analyse machine and sensor data and predict failures before they happen, so maintenance is done just in time rather than too early or too late. It reduces unplanned downtime, extends equipment life and cuts maintenance costs.'),array('How do we start with AI on the factory floor?','A focused predictive-maintenance or quality-inspection pilot on one line or machine is a common, low-risk start. It proves value on real data before you scale, and we build the MLOps to run it reliably in production.')),
			'sections' => array(array('h'=>'Where AI adds value in manufacturing','html'=>'<ul><li><strong>Predictive maintenance</strong> — fix machines before they fail.</li><li><strong>Quality assurance &amp; vision</strong> — automated defect detection.</li><li><strong>Process optimisation</strong> — tuning production for yield and efficiency.</li><li><strong>Demand planning</strong> — matching output to real demand.</li><li><strong>Supply chain</strong> — smarter forecasting and inventory.</li></ul>'),array('h'=>'Why Alugence for manufacturing','html'=>'<p>Downtime and defects are the two biggest destroyers of manufacturing margin, and both are highly predictable with the right data. We deploy AI that turns your machine and production data into early warnings and quality checks, integrated with your systems and measured against real output.</p>'),array('h'=>'How we work','html'=>'<p>Manufacturers often start with a <a href="/ai-consultancy/predictive-analytics/">predictive analytics</a> pilot for maintenance or quality, then scale into production with <a href="/ai-consultancy/mlops/">MLOps</a> for reliability.</p>')),
		),
		'/industries/marketing-agencies/' => array(
			'intro' => '<p>AI for marketing means two things at once: using AI to automate content, reporting and analysis, and winning visibility in AI search so your brand — and your clients\' brands — get cited by ChatGPT, Gemini and Perplexity. Alugence is uniquely placed to do both, because we run an AI consultancy <em>and</em> an AI search practice under one roof.</p>',
			'def' => '',
			'cards' => array(array('title'=>'Content automation','body'=>'<p>faster production, human-checked quality.</p>'),array('title'=>'Reporting','body'=>'<p>automated, always-current campaign reporting.</p>'),array('title'=>'Campaign analytics','body'=>'<p>deeper insight from your data.</p>'),array('title'=>'GEO/AEO for clients','body'=>'<p>get client brands cited in AI answers.</p>'),array('title'=>'AI search visibility','body'=>'<p>track and grow presence across AI engines.</p>')),
			'steps' => array(),
			'outcomes' => '<p>Most partners can help you <em>use</em> AI <em>or</em> help you get <em>found</em> by AI. Alugence does both — which matters, because AI is simultaneously a productivity tool and a new discovery channel eroding classic search traffic. Agencies can also white-label our AI search expertise to offer GEO and AEO to their own clients.</p>',
			'who' => '<p>Teams often start with <a href="/ai-consultancy/ai-training/">AI training</a> and <a href="/ai-consultancy/ai-automation/">automation</a> for content and reporting, plus an <a href="/ai-search/ai-search-visibility/">AI search visibility audit</a> to protect and grow discovery. Agencies add <a href="/ai-search/generative-engine-optimisation/">GEO</a> and <a href="/ai-search/answer-engine-optimisation/">AEO</a> as client services.</p>',
			'faqs' => array(array('How can marketing teams use AI?','Marketing teams use AI to automate content production, generate reporting, analyse campaigns, and personalise messaging — with humans reviewing quality and brand fit. Increasingly they also invest in AI search visibility (GEO and AEO) so their brand is cited when customers ask AI engines for recommendations.'),array('What is GEO/AEO for agency clients?','GEO (generative engine optimisation) and AEO (answer engine optimisation) get a brand cited in AI-generated answers and answer engines. Agencies can offer these to clients as new services — Alugence provides the expertise, tools and delivery, which agencies can white-label or refer. See GEO and AEO.'),array('Why use one partner for AI adoption and AI search?','Because they\'re two sides of the same shift. One partner means a joined-up strategy: using AI to work faster *and* staying visible as AI changes how customers discover brands. Alugence is the rare consultancy that credibly spans both. See our AI search consultancy.')),
			'sections' => array(array('h'=>'Where AI adds value in marketing','html'=>'<ul><li><strong>Content automation</strong> — faster production, human-checked quality.</li><li><strong>Reporting</strong> — automated, always-current campaign reporting.</li><li><strong>Campaign analytics</strong> — deeper insight from your data.</li><li><strong>GEO/AEO for clients</strong> — get client brands cited in AI answers.</li><li><strong>AI search visibility</strong> — track and grow presence across AI engines.</li></ul>'),array('h'=>'Why Alugence for marketing and agencies','html'=>'<p>Most partners can help you <em>use</em> AI <em>or</em> help you get <em>found</em> by AI. Alugence does both — which matters, because AI is simultaneously a productivity tool and a new discovery channel eroding classic search traffic. Agencies can also white-label our AI search expertise to offer GEO and AEO to their own clients.</p>'),array('h'=>'How we work','html'=>'<p>Teams often start with <a href="/ai-consultancy/ai-training/">AI training</a> and <a href="/ai-consultancy/ai-automation/">automation</a> for content and reporting, plus an <a href="/ai-search/ai-search-visibility/">AI search visibility audit</a> to protect and grow discovery. Agencies add <a href="/ai-search/generative-engine-optimisation/">GEO</a> and <a href="/ai-search/answer-engine-optimisation/">AEO</a> as client services.</p>')),
		),
		'/industries/professional-services/' => array(
			'intro' => '<p>AI for professional services means using artificial intelligence to automate document drafting, research and admin — so accountants, consultants and advisers spend more time on high-value, billable work. Alugence helps professional services firms deploy AI that speeds up delivery and protects margins, without compromising quality or confidentiality.</p>',
			'def' => '',
			'cards' => array(array('title'=>'Document drafting','body'=>'<p>first drafts of reports, letters and proposals.</p>'),array('title'=>'Research automation','body'=>'<p>faster gathering and summarising of information.</p>'),array('title'=>'Proposal generation','body'=>'<p>quicker, consistent pitches.</p>'),array('title'=>'Time capture','body'=>'<p>less admin around billing.</p>'),array('title'=>'Knowledge search','body'=>'<p>instant answers from your own documents.</p>')),
			'steps' => array(),
			'outcomes' => '<p>Your product is expertise and your risk is confidentiality. We build AI that augments your professionals — drafting and researching under their direction — with guardrails that protect client data and keep a human in control of what goes out the door. The payoff is capacity: more output from the same senior team.</p>',
			'who' => '<p>Firms typically begin with <a href="/ai-consultancy/ai-training/">AI training and enablement</a> plus a secure <a href="/ai-consultancy/llm-deployment/">LLM deployment</a>, then add a knowledge assistant grounded in their own documents.</p>',
			'faqs' => array(array('How can AI help a professional services firm?','AI can draft documents, automate research, generate proposals, reduce billing admin, and let staff instantly search the firm\'s own knowledge. This frees senior professionals from routine work so they focus on advisory, billable and relationship work — increasing capacity without extra headcount.'),array('Will AI compromise client confidentiality?','Not if it\'s deployed correctly. We use appropriate, secure tools, control what data is processed and where, and align with your confidentiality and GDPR obligations. A human always reviews AI-assisted work before it reaches a client. See AI governance.'),array('Can AI use our own templates and knowledge?','Yes. We ground AI assistants in your templates, precedents and knowledge base, so drafts and answers reflect your house style and expertise rather than generic output. That\'s what makes AI genuinely useful in a professional firm.')),
			'sections' => array(array('h'=>'Where AI adds value in professional services','html'=>'<ul><li><strong>Document drafting</strong> — first drafts of reports, letters and proposals.</li><li><strong>Research automation</strong> — faster gathering and summarising of information.</li><li><strong>Proposal generation</strong> — quicker, consistent pitches.</li><li><strong>Time capture</strong> — less admin around billing.</li><li><strong>Knowledge search</strong> — instant answers from your own documents.</li></ul>'),array('h'=>'Why Alugence for professional services','html'=>'<p>Your product is expertise and your risk is confidentiality. We build AI that augments your professionals — drafting and researching under their direction — with guardrails that protect client data and keep a human in control of what goes out the door. The payoff is capacity: more output from the same senior team.</p>'),array('h'=>'How we work','html'=>'<p>Firms typically begin with <a href="/ai-consultancy/ai-training/">AI training and enablement</a> plus a secure <a href="/ai-consultancy/llm-deployment/">LLM deployment</a>, then add a knowledge assistant grounded in their own documents.</p>')),
		),
		'/industries/real-estate/' => array(
			'intro' => '<p>AI in real estate means using artificial intelligence to automate valuations, generate listings, qualify leads and respond to buyers around the clock. Alugence helps estate agents, property firms and developers deploy practical AI that captures more enquiries, speeds up admin, and gives buyers instant answers — day or night.</p>',
			'def' => '',
			'cards' => array(array('title'=>'Automated valuations','body'=>'<p>faster, data-driven estimates.</p>'),array('title'=>'Listing generation','body'=>'<p>polished property descriptions in minutes.</p>'),array('title'=>'Lead qualification','body'=>'<p>sorting serious buyers from browsers.</p>'),array('title'=>'Viewing bookings','body'=>'<p>24/7 scheduling via chat or voice.</p>'),array('title'=>'Document processing','body'=>'<p>extracting data from contracts and forms.</p>')),
			'steps' => array(),
			'outcomes' => '<p>Property is a speed-to-lead business — the agent who responds first often wins. We deploy AI that answers enquiries instantly, qualifies and books viewings automatically, and takes the drudgery out of listings and paperwork, so your team spends time with the buyers and sellers who matter.</p>',
			'who' => '<p>Agencies often start with a <a href="/ai-consultancy/ai-chatbots/">chatbot</a> or <a href="/ai-consultancy/voice-ai/">voice AI</a> agent for enquiries and bookings, then add <a href="/ai-consultancy/ai-automation/">automation</a> for listings and document handling.</p>',
			'faqs' => array(array('How can AI help estate agents and property firms?','AI can produce automated valuations and listing descriptions, qualify leads, book viewings 24/7 through chat or voice, and process documents. This captures more enquiries — especially out of hours — and frees agents from admin to focus on closing deals.'),array('Can AI respond to buyers day and night?','Yes. An AI chatbot or voice agent can answer common buyer questions, qualify interest and book viewings around the clock, so no enquiry goes cold because it arrived after hours. Complex queries are handed to a human agent.'),array('What\'s a good first AI project for an agency?','Instant enquiry response and viewing booking is a strong, visible first step — it directly improves speed-to-lead, which drives conversions. We assess your enquiry flow and start where it captures the most business.')),
			'sections' => array(array('h'=>'Where AI adds value in real estate','html'=>'<ul><li><strong>Automated valuations</strong> — faster, data-driven estimates.</li><li><strong>Listing generation</strong> — polished property descriptions in minutes.</li><li><strong>Lead qualification</strong> — sorting serious buyers from browsers.</li><li><strong>Viewing bookings</strong> — 24/7 scheduling via chat or voice.</li><li><strong>Document processing</strong> — extracting data from contracts and forms.</li></ul>'),array('h'=>'Why Alugence for property','html'=>'<p>Property is a speed-to-lead business — the agent who responds first often wins. We deploy AI that answers enquiries instantly, qualifies and books viewings automatically, and takes the drudgery out of listings and paperwork, so your team spends time with the buyers and sellers who matter.</p>'),array('h'=>'How we work','html'=>'<p>Agencies often start with a <a href="/ai-consultancy/ai-chatbots/">chatbot</a> or <a href="/ai-consultancy/voice-ai/">voice AI</a> agent for enquiries and bookings, then add <a href="/ai-consultancy/ai-automation/">automation</a> for listings and document handling.</p>')),
		),
		'/industries/retail-ecommerce/' => array(
			'intro' => '<p>AI in retail and e-commerce means using artificial intelligence to personalise the customer experience, forecast demand, and turn customer data into decisions that lift revenue and margin. Alugence helps retailers and online brands deploy practical AI — from recommendations to inventory forecasting — that pays back in sales and efficiency.</p>',
			'def' => '',
			'cards' => array(array('title'=>'Personalisation & recommendations','body'=>'<p>relevant products, higher basket value.</p>'),array('title'=>'Demand forecasting','body'=>'<p>smarter buying and less waste.</p>'),array('title'=>'Customer analytics','body'=>'<p>understanding and predicting behaviour.</p>'),array('title'=>'Dynamic pricing','body'=>'<p>data-driven pricing decisions.</p>'),array('title'=>'Support automation','body'=>'<p>24/7 answers and order help.</p>')),
			'steps' => array(),
			'outcomes' => '<p>Retail runs on margins and volume, so AI has to move real numbers — conversion, basket size, stock efficiency — not just look clever. We prioritise use cases by revenue and cost impact, integrate with your commerce stack, and measure the result. And because Alugence also does AI search, we can help you get found by AI shoppers too.</p>',
			'who' => '<p>Retailers often start with <a href="/ai-consultancy/predictive-analytics/">predictive analytics</a> for forecasting or a personalisation pilot, plus support <a href="/ai-consultancy/ai-automation/">automation</a>. Brands worried about AI-driven discovery add <a href="/ai-search/ai-search-visibility/">AI search visibility</a>.</p>',
			'faqs' => array(array('How is AI used in retail and e-commerce?','AI powers product recommendations and personalisation, demand and inventory forecasting, customer and behavioural analytics, dynamic pricing, and support automation. Together these lift conversion and basket value while reducing waste and support costs.'),array('What AI project gives retailers the fastest return?','Personalisation and demand forecasting are common fast wins — recommendations lift revenue per visit, and better forecasting cuts overstock and stockouts. We assess your data and priorities and start where the payback is clearest.'),array('Can AI help my brand get found by AI shoppers?','Yes. As shoppers increasingly ask AI engines for product recommendations, being cited by AI matters. Alugence\'s AI search practice helps your brand appear when customers ask ChatGPT, Gemini or Perplexity what to buy — a capability most agencies can\'t offer.')),
			'sections' => array(array('h'=>'Where AI adds value in retail and e-commerce','html'=>'<ul><li><strong>Personalisation &amp; recommendations</strong> — relevant products, higher basket value.</li><li><strong>Demand forecasting</strong> — smarter buying and less waste.</li><li><strong>Customer analytics</strong> — understanding and predicting behaviour.</li><li><strong>Dynamic pricing</strong> — data-driven pricing decisions.</li><li><strong>Support automation</strong> — 24/7 answers and order help.</li></ul>'),array('h'=>'Why Alugence for retail','html'=>'<p>Retail runs on margins and volume, so AI has to move real numbers — conversion, basket size, stock efficiency — not just look clever. We prioritise use cases by revenue and cost impact, integrate with your commerce stack, and measure the result. And because Alugence also does AI search, we can help you get found by AI shoppers too.</p>'),array('h'=>'How we work','html'=>'<p>Retailers often start with <a href="/ai-consultancy/predictive-analytics/">predictive analytics</a> for forecasting or a personalisation pilot, plus support <a href="/ai-consultancy/ai-automation/">automation</a>. Brands worried about AI-driven discovery add <a href="/ai-search/ai-search-visibility/">AI search visibility</a>.</p>')),
		),
		'/pricing/' => array(
			'intro' => '<p>Alugence offers transparent, fixed-fee packages, monthly retainers and day rates across both practices — AI consultancy and AI search. Most clients start with a low-risk diagnostic, then scale into pilots, builds or ongoing support. All prices are "from", ex-VAT, and shown in GBP and USD via the currency toggle.</p>',
			'def' => '',
			'cards' => array(array('title'=>'Comparison table — consultancy tiers','body'=>'<div class="table-wrap"><table><thead><tr><th>Tier</th><th>From (GBP)</th><th>From (USD)</th><th>Duration</th><th>Best for</th></tr></thead><tbody><tr><td>AI Readiness Sprint</td><td>£3,500</td><td>$4,500</td><td>2 weeks</td><td>Low-risk start</td></tr><tr><td>AI Discovery &amp; Pilot</td><td>£15,000</td><td>$19,000</td><td>4–8 weeks</td><td>Validate a use case</td></tr><tr><td>AI Build &amp; Embed</td><td>£40,000</td><td>$50,000</td><td>8–16 weeks</td><td>Go to production</td></tr><tr><td>Fractional CAIO</td><td>£3,000/mo</td><td>$3,800/mo</td><td>Ongoing</td><td>AI leadership</td></tr><tr><td>Day rate</td><td>£950–£1,500</td><td>$1,200–$1,900</td><td>As needed</td><td>Ad-hoc support</td></tr></tbody></table></div>'),array('title'=>'Comparison table — AI search tiers','body'=>'<div class="table-wrap"><table><thead><tr><th>Tier</th><th>From (GBP)</th><th>From (USD)</th><th>Duration</th><th>Best for</th></tr></thead><tbody><tr><td>AI Visibility Audit</td><td>£2,500</td><td>$3,200</td><td>2–3 weeks</td><td>Know where you stand</td></tr><tr><td>GEO/AEO Sprint</td><td>£7,500</td><td>$9,500</td><td>4–6 weeks</td><td>Start earning citations</td></tr><tr><td>AI Search Retainer</td><td>£3,000/mo</td><td>$3,800/mo</td><td>Ongoing (3-mo min)</td><td>Sustained growth</td></tr><tr><td>Enterprise / bespoke</td><td>POA</td><td>POA</td><td>Scoped</td><td>Large / multi-brand</td></tr></tbody></table></div>')),
			'steps' => array(),
			'outcomes' => '',
			'who' => '',
			'faqs' => array(array('How much does AI consulting cost?','AI consulting costs vary by scope. At Alugence, fixed-fee diagnostics start from £3,500 / $4,500 (a two-week AI Readiness Sprint), pilots from £15,000 / $19,000, and production builds from £40,000 / $50,000. Ongoing support is available as a monthly retainer or fractional leadership. All prices are ex-VAT and confirmed after scoping.'),array('What\'s included in the price?','Each package lists its deliverables — for example, the AI Readiness Sprint includes a readiness score, data and process audit, regulatory check, prioritised use cases and a written report. Nothing is hidden: your scoping call turns the "from" price into a confirmed figure with defined outcomes.'),array('Do you offer fixed fees?','Yes. Most engagements are fixed-fee against a defined scope, which keeps budgets predictable. Where work can\'t be scoped to a fixed fee — such as exploratory advisory — we use a transparent day rate agreed in advance.'),array('What is the payback window?','It depends on the use case, but automation and efficiency projects typically target payback within 6–12 months. Our AI ROI Calculator gives an indicative annual saving and readiness score so you can estimate payback before committing.'),array('Are prices ex-VAT?','Yes. All listed prices are exclusive of VAT. UK clients are charged VAT where applicable; US clients are invoiced in USD.'),array('Do you work with US clients?','Yes. Alugence works with UK and US clients, with pricing shown in GBP and USD. Engagements run remotely, and schema/areaServed on our site reflects both markets.')),
			'sections' => array(array('h'=>'AI consultancy pricing','html'=>'<p><em>(Arm 1 — AI transformation. Prices indicative; confirm before launch.)</em></p>
<h3>AI Readiness Sprint — from £3,500 / $4,500 · 2 weeks</h3>
<p>A low-risk starting point. You get a readiness score, a data and process audit, a regulatory perimeter check, 3–5 prioritised use cases scored on value/effort/risk, and a written report.</p>
<p><em>Best for:</em> first-time buyers wanting a low-risk start.</p>
<p><a href="/ai-consultancy/ai-readiness/">Related: AI Readiness Assessment →</a> · <a href="/contact/">Book a scoping call</a></p>
<h3>AI Discovery &amp; Pilot — from £15,000 / $19,000 · 4–8 weeks</h3>
<p>A working prototype/PoC on your real data. Includes solution design, a deployment plan, a named senior consultant lead, and technical documentation.</p>
<p><em>Best for:</em> validating a use case before scaling.</p>
<p><a href="/ai-consultancy/ai-proof-of-concept/">Related: AI Proof of Concept →</a></p>
<h3>AI Build &amp; Embed — from £40,000 / $50,000 · 8–16 weeks</h3>
<p>Production deployment and integration with your existing systems. Includes GDPR/security posture, staff onboarding and training, plus a runbook and monitoring handover.</p>
<p><em>Best for:</em> rolling AI into live operations.</p>
<p><a href="/ai-consultancy/ai-implementation/">Related: AI Implementation →</a></p>
<h3>Fractional Chief AI Officer — from £3,000 / $3,800 per month · ongoing (rolling)</h3>
<p>Senior AI leadership without a full-time hire: strategy, governance, vendor selection, roadmap ownership and board reporting. Typically 2–4 days per month.</p>
<p><em>Best for:</em> SMEs and mid-market needing AI leadership.</p>
<p><a href="/ai-consultancy/fractional-ai-officer/">Related: Fractional CAIO →</a></p>
<h3>Day rate — £950–£1,500 / $1,200–$1,900 · as needed</h3>
<p>Advisory, workshops or delivery where a fixed fee isn\'t practical.</p>
<p><em>Best for:</em> ad-hoc or scoped support.</p>'),array('h'=>'AI search pricing','html'=>'<p><em>(Arm 2 — GEO / AEO / AI SEO. Prices indicative; confirm before launch.)</em></p>
<h3>AI Visibility Audit — from £2,500 / $3,200 · 2–3 weeks</h3>
<p>Your baseline visibility across ChatGPT, Gemini, Perplexity and Google AI Overviews, plus a GEO/AEO gap analysis, a prioritised action plan and a competitor benchmark.</p>
<p><em>Best for:</em> understanding where you stand in AI search.</p>
<p><a href="/ai-search/ai-search-visibility/">Related: AI Search Visibility →</a></p>
<h3>GEO/AEO Sprint — from £7,500 / $9,500 · 4–6 weeks</h3>
<p>Implementation of your priority fixes: entity/schema work, content restructure, llms.txt, and FAQ + answer-first rewrites for key pages.</p>
<p><em>Best for:</em> a focused push to start earning AI citations.</p>
<p><a href="/ai-search/generative-engine-optimisation/">Related: GEO →</a> · <a href="/ai-search/answer-engine-optimisation/">AEO →</a></p>
<h3>AI Search Retainer — from £3,000 / $3,800 per month · ongoing (3-month min)</h3>
<p>Continuous visibility tracking, content optimisation, citation building and monthly AI share-of-voice reporting.</p>
<p><em>Best for:</em> sustained growth in AI search visibility.</p>
<h3>Enterprise / bespoke — POA · scoped</h3>
<p>Multi-brand or large-catalogue programmes, custom tracking and team training, priced on scope.</p>
<p><em>Best for:</em> larger orgs and agencies.</p>'),array('h'=>'How we scope and what\'s included','html'=>'<p>Every engagement is scoped before we start, so the "from" price becomes a confirmed figure with no hidden fees. Fixed-fee packages have defined deliverables; retainers have a monthly scope and reporting cadence; day-rate work is booked against an agreed brief. Prices are ex-VAT and indicative until scoped. We\'re happy to work in GBP or USD.</p>
<h3>Comparison table — consultancy tiers</h3>
<div class="table-wrap"><table><thead><tr><th>Tier</th><th>From (GBP)</th><th>From (USD)</th><th>Duration</th><th>Best for</th></tr></thead><tbody><tr><td>AI Readiness Sprint</td><td>£3,500</td><td>$4,500</td><td>2 weeks</td><td>Low-risk start</td></tr><tr><td>AI Discovery &amp; Pilot</td><td>£15,000</td><td>$19,000</td><td>4–8 weeks</td><td>Validate a use case</td></tr><tr><td>AI Build &amp; Embed</td><td>£40,000</td><td>$50,000</td><td>8–16 weeks</td><td>Go to production</td></tr><tr><td>Fractional CAIO</td><td>£3,000/mo</td><td>$3,800/mo</td><td>Ongoing</td><td>AI leadership</td></tr><tr><td>Day rate</td><td>£950–£1,500</td><td>$1,200–$1,900</td><td>As needed</td><td>Ad-hoc support</td></tr></tbody></table></div>
<h3>Comparison table — AI search tiers</h3>
<div class="table-wrap"><table><thead><tr><th>Tier</th><th>From (GBP)</th><th>From (USD)</th><th>Duration</th><th>Best for</th></tr></thead><tbody><tr><td>AI Visibility Audit</td><td>£2,500</td><td>$3,200</td><td>2–3 weeks</td><td>Know where you stand</td></tr><tr><td>GEO/AEO Sprint</td><td>£7,500</td><td>$9,500</td><td>4–6 weeks</td><td>Start earning citations</td></tr><tr><td>AI Search Retainer</td><td>£3,000/mo</td><td>$3,800/mo</td><td>Ongoing (3-mo min)</td><td>Sustained growth</td></tr><tr><td>Enterprise / bespoke</td><td>POA</td><td>POA</td><td>Scoped</td><td>Large / multi-brand</td></tr></tbody></table></div>')),
		),
