/** Full content record for a path (or current page). */
function tf_content( $path = '' ) {
	if ( ! $path ) {
		if ( is_front_page() ) { $path = '/'; }
		else { $u = get_permalink( get_queried_object_id() ); $path = $u ? wp_parse_url( $u, PHP_URL_PATH ) : ''; }
	}
	if ( ! $path ) { return null; }
	$path = trailingslashit( '/' . ltrim( $path, '/' ) );
	$s = tf_content_store();
	return isset( $s[ $path ] ) ? $s[ $path ] : null;
}

/** A named block ('intro','def','outcomes','who') as safe HTML, or '' if absent. */
function tf_c( $key, $path = '' ) {
	$r = tf_content( $path );
	return ( $r && ! empty( $r[ $key ] ) && is_string( $r[ $key ] ) ) ? $r[ $key ] : '';
}

/** A content section body (HTML) whose heading matches $pattern (regex), or ''. */
function tf_c_section( $pattern, $path = '' ) {
	$r = tf_content( $path );
	if ( ! $r || empty( $r['sections'] ) ) { return ''; }
	foreach ( $r['sections'] as $sec ) {
		if ( preg_match( '~' . $pattern . '~i', $sec['h'] ) ) { return $sec['html']; }
	}
	return '';
}

/** Allowed inline HTML for content blocks (matches what the pack emits). */
function tf_content_kses() {
	return array(
		'p'=>array(), 'a'=>array('href'=>array()), 'strong'=>array(), 'em'=>array(),
		'ul'=>array(), 'ol'=>array(), 'li'=>array(), 'h3'=>array(), 'h4'=>array(),
		'blockquote'=>array(), 'code'=>array(),
		'table'=>array(), 'thead'=>array(), 'tbody'=>array(), 'tr'=>array(), 'th'=>array(), 'td'=>array(),
		'div'=>array('class'=>array()),
	);
}

